+import { Redis } from "ioredis";
+import { findKey } from "../auth/keys.js";
+
+const redis = new Redis(process.env.REDIS_URL);
+
+export async function rateLimit(token: string): Promise<boolean> {
+  const key = await findKey(token);
+  if (!key) return false;
+  const used = await redis.incr(`limit:${key.id}`);
+  if (used === 1) await redis.expire(`limit:${key.id}`, 60);
+  return used <= key.rateLimit;
+}

